private static async Task<FederationWorkspaceEntity> UpsertWorkspaceAsync(
    McpDbContext db,
    string proxyId,
    FederationWorkspaceRegistrationRequest request,
    DateTimeOffset now,
    CancellationToken cancellationToken)
{
    ArgumentException.ThrowIfNullOrWhiteSpace(request.WorkspacePath);
    var identity = await WorkspaceIdentity.ResolveAsync(
            request.WorkspacePath,
            TimeSpan.FromSeconds(5),
            cancellationToken)
        .ConfigureAwait(false);
    var canonicalPath = identity.NormalizedPath;
    var globalWorkspaceId = string.IsNullOrWhiteSpace(request.GlobalWorkspaceId)
        ? CreateGlobalWorkspaceId(proxyId, identity.StorageKey)
        : request.GlobalWorkspaceId.Trim();

    var entity = db.FederationWorkspaces.Local.FirstOrDefault(w =>
            string.Equals(w.ProxyId, proxyId, StringComparison.OrdinalIgnoreCase) &&
            string.Equals(w.WorkspacePath, canonicalPath, StringComparison.OrdinalIgnoreCase))
        ?? db.FederationWorkspaces.FirstOrDefault(w => w.ProxyId == proxyId && w.WorkspacePath == canonicalPath);

    if (entity is null)
    {
        entity = new FederationWorkspaceEntity
        {
            ProxyId = proxyId,
            WorkspacePath = canonicalPath,
            GlobalWorkspaceId = globalWorkspaceId,
            CanonicalWorkspaceId = globalWorkspaceId,
            CreatedAtUtc = now,
        };
        db.FederationWorkspaces.Add(entity);
    }

    entity.GlobalWorkspaceId = globalWorkspaceId;
    entity.CanonicalWorkspaceId = globalWorkspaceId;
    entity.WorkspacePath = canonicalPath;
    entity.WorkspaceName = request.WorkspaceName;
    entity.IsEnabled = request.IsEnabled;
    entity.Version = request.Version;
    entity.MetadataJson = request.MetadataJson;
    entity.LastSeenUtc = now;
    EnsureFederatedWorkspaceRow(db, entity, now);
    return entity;
}

public override async ValueTask<FederationApplyResult> ApplyAsync(FederationStateOperation operation, CancellationToken cancellationToken)
{
    ArgumentNullException.ThrowIfNull(operation);
    await using var scope = ScopeFactory.CreateAsyncScope();
    var db = scope.ServiceProvider.GetRequiredService<McpDbContext>();

    if (string.Equals(operation.HttpMethod, "DELETE", StringComparison.OrdinalIgnoreCase))
    {
        var resourceId = operation.ResourceId;
        if (string.IsNullOrWhiteSpace(resourceId))
            return Conflict("Tools/buckets delete operation does not identify a resource id.");

        var tools = await db.ToolDefinitions
            .Include(t => t.Tags)
            .Where(t => t.Name == resourceId || t.BucketName == resourceId)
            .ToListAsync(cancellationToken)
            .ConfigureAwait(false);
        var buckets = await db.ToolBuckets
            .Where(b => b.Name == resourceId)
            .ToListAsync(cancellationToken)
            .ConfigureAwait(false);
        db.ToolDefinitions.RemoveRange(tools);
        db.ToolBuckets.RemoveRange(buckets);
        await db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return new FederationApplyResult { Applied = true, Version = null };
    }

    ToolsBucketsPayload? payload;
    try
    {
        payload = (ToolsBucketsPayload?)JsonSerializer.Deserialize(operation.PayloadJson, typeof(ToolsBucketsPayload), FederationAdapterJsonContext.Default);
    }
    catch (JsonException ex)
    {
        return Conflict($"Tools/buckets federation payload is invalid JSON: {ex.Message}");
    }

    if (payload is null || (payload.Buckets.Count == 0 && payload.Tools.Count == 0))
        return Conflict("Tools/buckets federation payload does not contain bucket or tool rows.");

    foreach (var bucket in payload.Buckets)
        await UpsertBucketAsync(db, bucket, cancellationToken).ConfigureAwait(false);
    foreach (var tool in payload.Tools)
        await UpsertToolAsync(db, tool, cancellationToken).ConfigureAwait(false);

    await db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    return new FederationApplyResult
    {
        Applied = true,
        Version = await GetVersionAsync(operation.ResourceId ?? "*", cancellationToken).ConfigureAwait(false),
    };
}

public override async ValueTask<FederationApplyResult> ApplyAsync(FederationStateOperation operation, CancellationToken cancellationToken)
