private static async Task UpsertAgentDefinitionAsync(
    McpDbContext db,
    AgentDefinitionPayload definition,
    CancellationToken cancellationToken)
{
    var id = definition.Id.Trim();
    var entity = await db.AgentDefinitions
        .FirstOrDefaultAsync(a => a.Id == id, cancellationToken)
        .ConfigureAwait(false);
    if (entity is null)
    {
        entity = new AgentDefinitionEntity
        {
            Id = id,
            CreatedAt = definition.CreatedAt ?? DateTime.UtcNow,
        };
        db.AgentDefinitions.Add(entity);
    }

    entity.DisplayName = definition.DisplayName ?? entity.DisplayName;
    entity.DefaultLaunchCommand = definition.DefaultLaunchCommand ?? entity.DefaultLaunchCommand;
    entity.DefaultInstructionFile = definition.DefaultInstructionFile ?? entity.DefaultInstructionFile;
    if (definition.DefaultModelsJson is not null)
    {
        var models = ParseWireList(definition.DefaultModelsJson) ?? [];
        entity.Models.Clear();
        for (var i = 0; i < models.Count; i++)
            entity.Models.Add(new AgentDefinitionModelEntity { WorkspaceId = entity.WorkspaceId, Ordinal = i, Model = models[i] });
    }

    entity.DefaultBranchStrategy = definition.DefaultBranchStrategy ?? entity.DefaultBranchStrategy;
    entity.DefaultSeedPrompt = definition.DefaultSeedPrompt ?? entity.DefaultSeedPrompt;
    entity.IsBuiltIn = definition.IsBuiltIn;
    entity.ModifiedAt = definition.ModifiedAt ?? DateTime.UtcNow;
}

public async Task<BucketMutationResult> AddBucketAsync(BucketAddRequest request, CancellationToken ct = default)
{
    var name = (request.Name ?? "").Trim().ToLowerInvariant();
    if (string.IsNullOrEmpty(name))
        return new BucketMutationResult(false, "Bucket name is required.");

    var exists = await _db.ToolBuckets
        .IgnoreQueryFilters()
        .AnyAsync(b => b.Name == name, ct)
        .ConfigureAwait(false);
    if (exists)
        return new BucketMutationResult(false, $"Bucket '{name}' already exists.");

    var entity = new ToolBucketEntity
    {
        Name = name,
        Owner = (request.Owner ?? "").Trim(),
        Repo = (request.Repo ?? "").Trim(),
        Branch = string.IsNullOrWhiteSpace(request.Branch) ? "main" : request.Branch.Trim(),
        ManifestPath = string.IsNullOrWhiteSpace(request.ManifestPath) ? "/" : request.ManifestPath.Trim(),
        DateTimeCreated = DateTimeOffset.UtcNow,
    };

    if (string.IsNullOrEmpty(entity.Owner) || string.IsNullOrEmpty(entity.Repo))
        return new BucketMutationResult(false, "Owner and Repo are required.");

    _db.ToolBuckets.Add(entity);
    await _db.SaveChangesAsync(ct).ConfigureAwait(false);
    await PublishChangeSafeAsync(ChangeEventActions.Created, name, ct).ConfigureAwait(false);

    _logger.LogInformation("Bucket added: {Name} ({Owner}/{Repo})", name, entity.Owner, entity.Repo);
    return new BucketMutationResult(true, Bucket: ToDto(entity));
}

/// <inheritdoc />
public async Task<BucketMutationResult> RemoveBucketAsync(string bucketName, bool uninstallTools = false, CancellationToken ct = default)
{
    var name = (bucketName ?? "").Trim().ToLowerInvariant();
    var entity = await GetVisibleBucketsQuery().FirstOrDefaultAsync(b => b.Name == name, ct).ConfigureAwait(false);
    if (entity is null)
        return new BucketMutationResult(false, $"Bucket '{name}' not found.");

    if (uninstallTools)
    {
        var tools = await _db.ToolDefinitions.Where(t => t.BucketName == name).ToListAsync(ct).ConfigureAwait(false);
        _db.ToolDefinitions.RemoveRange(tools);
        _logger.LogInformation("Uninstalled {Count} tools from bucket '{Name}'", tools.Count, name);
        foreach (var tool in tools)
        {
            await PublishToolRegistryChangeSafeAsync(ChangeEventActions.Deleted, tool.Id.ToString(), ct).ConfigureAwait(false);
        }
    }

    var dto = ToDto(entity);
    _db.ToolBuckets.Remove(entity);
    await _db.SaveChangesAsync(ct).ConfigureAwait(false);
    await PublishChangeSafeAsync(ChangeEventActions.Deleted, name, ct).ConfigureAwait(false);

    _logger.LogInformation("Bucket removed: {Name}", name);
    return new BucketMutationResult(true, Bucket: dto);
}

public async Task<ToolMutationResult> InstallAsync(string bucketName, string toolName, string? workspacePath = null, CancellationToken ct = default)
{
    var name = (bucketName ?? "").Trim().ToLowerInvariant();
    var bucket = await GetVisibleBucketsQuery().AsNoTracking().FirstOrDefaultAsync(b => b.Name == name, ct).ConfigureAwait(false);
    if (bucket is null)
        return new ToolMutationResult(false, $"Bucket '{name}' not found.");

    var manifests = await FetchManifestsAsync(bucket, ct).ConfigureAwait(false);
    if (manifests is null)
        return new ToolMutationResult(false, $"Failed to read manifests from {bucket.Owner}/{bucket.Repo}.");

    var manifest = manifests.FirstOrDefault(m => string.Equals(m.Name, toolName, StringComparison.OrdinalIgnoreCase));
    if (manifest is null)
        return new ToolMutationResult(false, $"Tool '{toolName}' not found in bucket '{name}'.");

    // Create via the registry service (handles uniqueness, normalization).
    var result = await _toolRegistry.CreateAsync(new ToolCreateRequest(
        manifest.Name,
        manifest.Description,
        manifest.Tags,
        manifest.ParameterSchema,
        manifest.CommandTemplate,
        workspacePath), ct).ConfigureAwait(false);

    if (!result.Success)
        return result;

    // Stamp the bucket provenance.
    var entity = await _db.ToolDefinitions.FirstOrDefaultAsync(t => t.Id == result.Tool!.Id, ct).ConfigureAwait(false);
    if (entity is not null)
    {
        entity.BucketName = name;
        await _db.SaveChangesAsync(ct).ConfigureAwait(false);
    }

    _logger.LogInformation("Installed tool '{Tool}' from bucket '{Bucket}'", manifest.Name, name);
    return result;
}

/// <inheritdoc />
public async Task<BucketSyncResult> SyncAsync(string bucketName, CancellationToken ct = default)
{
    var name = (bucketName ?? "").Trim().ToLowerInvariant();
    var bucket = await GetVisibleBucketsQuery().FirstOrDefaultAsync(b => b.Name == name, ct).ConfigureAwait(false);
    if (bucket is null)
        return new BucketSyncResult(false, $"Bucket '{name}' not found.");

    var manifests = await FetchManifestsAsync(bucket, ct).ConfigureAwait(false);
    if (manifests is null)
        return new BucketSyncResult(false, $"Failed to read manifests from {bucket.Owner}/{bucket.Repo}.");

    var installed = await _db.ToolDefinitions
        .Include(t => t.Tags)
        .Where(t => t.BucketName == name)
        .ToListAsync(ct).ConfigureAwait(false);

    int updated = 0, unchanged = 0;
    var manifestByName = manifests.ToDictionary(m => m.Name, StringComparer.OrdinalIgnoreCase);

    foreach (var tool in installed)
    {
        if (!manifestByName.TryGetValue(tool.Name, out var manifest))
        {
            unchanged++;
            continue;
        }

        var changed = false;
        if (tool.Description != manifest.Description) { tool.Description = manifest.Description; changed = true; }
        if (tool.ParameterSchema != manifest.ParameterSchema) { tool.ParameterSchema = manifest.ParameterSchema; changed = true; }
        if (tool.CommandTemplate != manifest.CommandTemplate) { tool.CommandTemplate = manifest.CommandTemplate; changed = true; }

        var currentTags = tool.Tags.Select(t => t.Tag).OrderBy(t => t).ToList();
        var newTags = manifest.Tags.Select(t => t.Trim().ToLowerInvariant()).OrderBy(t => t).Distinct().ToList();
        if (!currentTags.SequenceEqual(newTags))
        {
            tool.Tags.Clear();
            foreach (var tag in newTags)
                tool.Tags.Add(new ToolDefinitionTagEntity { Tag = tag });
            changed = true;
        }

        if (changed)
        {
            tool.DateTimeModified = DateTimeOffset.UtcNow;
            updated++;
        }
        else
        {
            unchanged++;
        }
    }

    bucket.DateTimeLastSynced = DateTimeOffset.UtcNow;
    await _db.SaveChangesAsync(ct).ConfigureAwait(false);
    await PublishChangeSafeAsync(ChangeEventActions.Updated, name, ct).ConfigureAwait(false);

    _logger.LogInformation("Bucket sync '{Name}': {Updated} updated, {Unchanged} unchanged", name, updated, unchanged);
    return new BucketSyncResult(true, Updated: updated, Unchanged: unchanged);
}

public async Task<ToolMutationResult> CreateAsync(ToolCreateRequest request, CancellationToken ct = default)
{
    var name = (request.Name ?? "").Trim();
    if (string.IsNullOrEmpty(name))
        return new ToolMutationResult(false, "Tool name is required.");

    var scope = NormalizeScope(request.WorkspacePath);

    // Unique name per scope.
    var exists = await _db.ToolDefinitions.AnyAsync(
        t => t.Name == name && t.WorkspacePath == scope.WorkspacePath, ct).ConfigureAwait(false);
    if (exists)
        return new ToolMutationResult(false, $"Tool '{name}' already exists in this scope.");

    var now = DateTimeOffset.UtcNow;
    var entity = new ToolDefinitionEntity
    {
        Name = name,
        Description = (request.Description ?? "").Trim(),
        ParameterSchema = request.ParameterSchema,
        CommandTemplate = request.CommandTemplate,
        WorkspacePath = scope.WorkspacePath,
        WorkspaceId = scope.WorkspaceId,
        DateTimeCreated = now,
        DateTimeModified = now,
    };

    foreach (var tag in NormalizeTags(request.Tags))
        entity.Tags.Add(new ToolDefinitionTagEntity { Tag = tag, WorkspaceId = scope.WorkspaceId });

    _db.ToolDefinitions.Add(entity);
    await _db.SaveChangesAsync(ct).ConfigureAwait(false);
    await PublishChangeSafeAsync(ChangeEventActions.Created, entity.Id.ToString(), ct).ConfigureAwait(false);

    _logger.LogInformation("Tool created: {Name} (scope: {Scope})", name, scope.WorkspacePath ?? "global");
    return new ToolMutationResult(true, Tool: ToDto(entity));
}

/// <inheritdoc />
public async Task<ToolMutationResult> UpdateAsync(int id, ToolUpdateRequest request, CancellationToken ct = default)
{
    var entity = await _db.ToolDefinitions.Include(t => t.Tags)
        .FirstOrDefaultAsync(t => t.Id == id, ct).ConfigureAwait(false);
    if (entity is null)
        return new ToolMutationResult(false, $"Tool {id} not found.");

    if (request.Name is not null)
    {
        var name = request.Name.Trim();
        if (string.IsNullOrEmpty(name))
            return new ToolMutationResult(false, "Tool name cannot be empty.");
        entity.Name = name;
    }

    if (request.Description is not null)
        entity.Description = request.Description.Trim();

    if (request.ParameterSchema is not null)
        entity.ParameterSchema = request.ParameterSchema;

    if (request.CommandTemplate is not null)
        entity.CommandTemplate = request.CommandTemplate;

    if (request.WorkspacePath is not null)
        ApplyScope(entity, NormalizeScope(request.WorkspacePath));

    var now = DateTimeOffset.UtcNow;
    IReadOnlyList<string>? tagsOverride = null;
    if (request.Tags is not null)
    {
        tagsOverride = NormalizeTags(request.Tags);
        await ReplaceTagsAsync(entity, tagsOverride, now, ct).ConfigureAwait(false);
    }

    entity.DateTimeModified = now;
    await _db.SaveChangesAsync(ct).ConfigureAwait(false);
    await PublishChangeSafeAsync(ChangeEventActions.Updated, entity.Id.ToString(), ct).ConfigureAwait(false);

    _logger.LogInformation("Tool updated: {Name} (id: {Id})", entity.Name, entity.Id);
    return new ToolMutationResult(true, Tool: ToDto(entity, tagsOverride));
}

/// <inheritdoc />
public async Task<ToolMutationResult> DeleteAsync(int id, CancellationToken ct = default)
{
    var entity = await _db.ToolDefinitions.Include(t => t.Tags)
        .FirstOrDefaultAsync(t => t.Id == id, ct).ConfigureAwait(false);
    if (entity is null)
        return new ToolMutationResult(false, $"Tool {id} not found.");

    var dto = ToDto(entity);
    var now = DateTimeOffset.UtcNow;
    foreach (var tag in entity.Tags)
        MarkSoftDeleted(tag, now, "tool_deleted");
    entity.DateTimeModified = now;
    MarkSoftDeleted(entity, now, "tool_deleted");
    await _db.SaveChangesAsync(ct).ConfigureAwait(false);
    await PublishChangeSafeAsync(ChangeEventActions.Deleted, dto.Id.ToString(), ct).ConfigureAwait(false);

    _logger.LogInformation("Tool deleted: {Name} (id: {Id})", dto.Name, dto.Id);
    return new ToolMutationResult(true, Tool: dto);
}

private async Task<WorkspaceMutationResult> UpdateDatabaseAsync(string workspacePath, WorkspaceUpdateRequest request, CancellationToken ct)
{
    var normalized = NormalizePath(workspacePath);
    await s_writeLock.WaitAsync(ct).ConfigureAwait(false);
    try
    {
        await EnsureBootstrappedAsync(ct).ConfigureAwait(false);
        var entity = await FindActiveWorkspaceAsync(normalized, ct).ConfigureAwait(false);
        if (entity is null)
            return new WorkspaceMutationResult(false, $"Workspace not found: {normalized}");

        ApplyUpdate(entity, request, normalized);
        await _db!.SaveChangesAsync(ct).ConfigureAwait(false);
        await WriteProjectionFromDatabaseAsync(ct).ConfigureAwait(false);
        _logger.LogInformation("Workspace updated: {Name} at {Path}", entity.Name, entity.WorkspacePath);
        await PublishChangeSafeAsync(ChangeEventActions.Updated, normalized, ct).ConfigureAwait(false);
        return new WorkspaceMutationResult(true, Workspace: await ToDtoAsync(entity, ct).ConfigureAwait(false));
    }
    finally
    {
        s_writeLock.Release();
    }
}

private async Task<WorkspaceMutationResult> DeleteDatabaseAsync(string workspacePath, CancellationToken ct)
{
    var normalized = NormalizePath(workspacePath);
    await s_writeLock.WaitAsync(ct).ConfigureAwait(false);
    try
    {
        await EnsureBootstrappedAsync(ct).ConfigureAwait(false);
        var entity = await FindActiveWorkspaceAsync(normalized, ct).ConfigureAwait(false);
        if (entity is null)
            return new WorkspaceMutationResult(false, $"Workspace not found: {normalized}");

        var dto = await ToDtoAsync(entity, ct).ConfigureAwait(false);
        entity.IsDeleted = true;
        entity.DeletedAtUtc = DateTimeOffset.UtcNow;
        entity.DeletedBy = nameof(WorkspaceService);
        entity.DeleteReason = "workspace_delete";
        entity.DateTimeModified = entity.DeletedAtUtc.Value;
        await _db!.SaveChangesAsync(ct).ConfigureAwait(false);
        await WriteProjectionFromDatabaseAsync(ct).ConfigureAwait(false);
        _logger.LogInformation("Workspace soft-deleted: {Name} at {Path}", dto.Name, dto.WorkspacePath);
        await PublishChangeSafeAsync(ChangeEventActions.Deleted, normalized, ct).ConfigureAwait(false);
        return new WorkspaceMutationResult(true, Workspace: dto);
    }
    finally
    {
        s_writeLock.Release();
    }
}
